\begin{align*}
v(\boldsymbol{x})=\left\{\begin{array}{cccll}
v_{\mathrm i}(\boldsymbol{x})\hspace{-0.65em}&=\hspace{-0.65em}&{\mathcal H}(\boldsymbol{x})&\text{if}&\boldsymbol{x}\in\Omega \vspace{0.125em}\\
v_{\mathrm e}(\boldsymbol{x})\hspace{-0.65em}&=\hspace{-0.65em}&-\widetilde{b}_l(\boldsymbol{x})&\text{if}&\boldsymbol{x}\notin\Omega.
\end{array}\right.
\end{align*}
Hence

Hence, we obtain \cref{NewModeling}, and we can further see that $v_{\mathrm i}$ and $v_{\mathrm e}$ satisfy
\begin{align}
-\Delta v_{\mathrm i}&=0~~~~~~\text{in }  \Omega \\
-\Delta v_{\mathrm e}&=0~~~~~~\text{in }  {\mathbb R}^3\setminus\overline{\Omega} \\
v_{\mathrm i}=v_{\mathrm e}&=-\widetilde{b}_l~~~\text{on } \partial\Omega, \end{align}
respectively, where \cref{v_eharmonic} comes from \cref{TrueLocalField}; $-\Delta\widetilde{b}_l=1_{\Omega}P(D)\chi$, i.e. $-\Delta\widetilde{b}_l=P(D)\chi$ in $\Omega$, and $-\Delta\widetilde{b}_l=0$ in ${\mathbb R}^3\setminus\overline{\Omega}$.

To prove \cref{DistLapIncompatibility}, let $\varphi\in C_0^{\infty}({\mathbb R}^3)$, and we consider
\begin{align*}
\int_{{\mathbb R}^3}v(\boldsymbol{x})\left(-\Delta\varphi\right)(\boldsymbol{x})\mathrm{d}\boldsymbol{x}&=\int_{\Omega}v_{\mathrm i}(\boldsymbol{x})\left(-\Delta\varphi\right)(\boldsymbol{x})\mathrm{d}\boldsymbol{x}+\int_{{\mathbb R}^3\setminus\overline{\Omega}}v_{\mathrm e}(\boldsymbol{x})\left(-\Delta\varphi\right)(\boldsymbol{x})\mathrm{d}\boldsymbol{x}\\
&=I_1+I_2
\end{align*}

Using \cref{v_iharmonic,vboundaryconti} and the Green's identity (e.g. \cite{Evans2010}), we have
\begin{align*}
I_1&=\int_{\Omega}\left[\varphi(\boldsymbol{x})\left(\Delta v_{\mathrm i}\right)(\boldsymbol{x})-v_{\mathrm i}(\boldsymbol{x})\left(\Delta\varphi\right)(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{x}\\
&=\int_{\partial\Omega}\left[\varphi(\boldsymbol{x})\frac{\partial v_{\mathrm i}}{\partial\boldsymbol{n}}(\boldsymbol{x})-v_{\mathrm i}(\boldsymbol{x})\frac{\partial\varphi}{\partial\boldsymbol{n}}(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{\sigma}(\boldsymbol{x})=\int_{\partial\Omega}\left[\varphi(\boldsymbol{x})\frac{\partial v_{\mathrm i}}{\partial\boldsymbol{n}}(\boldsymbol{x})+\widetilde{b}_l(\boldsymbol{x})\frac{\partial\varphi}{\partial\boldsymbol{n}}(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{\sigma}(\boldsymbol{x}).
\end{align*}

Similarly using \cref{v_eharmonic,vboundaryconti}, we also have
\begin{align*}
I_2&=\int_{{\mathbb R}^3\setminus\overline{\Omega}}\left[\varphi(\boldsymbol{x})\left(\Delta v_{\mathrm e}\right)(\boldsymbol{x})-v_{\mathrm e}(\boldsymbol{x})\left(\Delta\varphi\right)(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{x}\\
&=\int_{\partial\Omega}\left[-\varphi(\boldsymbol{x})\frac{\partial v_{\mathrm e}}{\partial\boldsymbol{n}}(\boldsymbol{x})+v_{\mathrm e}(\boldsymbol{x})\frac{\partial\varphi}{\partial\boldsymbol{n}}(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{\sigma}(\boldsymbol{x})=-\int_{\partial\Omega}\left[\varphi(\boldsymbol{x})\frac{\partial v_{\mathrm e}}{\partial\boldsymbol{n}}(\boldsymbol{x})+\widetilde{b}_l(\boldsymbol{x})\frac{\partial\varphi}{\partial\boldsymbol{n}}(\boldsymbol{x})\right]\mathrm{d}\boldsymbol{\sigma}(\boldsymbol{x})
\end{align*}
where the second equality comes from the fact that we need to compute the inward normal derivatives on $\partial\Omega$.

To prove 2, we assume on the contrary that there exists $\boldsymbol{x}\in\partial\Omega$ such that
\begin{align*}
\frac{\partial v_{\mathrm i}}{\partial\boldsymbol{n}}=\frac{\partial v_{\mathrm e}}{\partial\boldsymbol{n}}
\end{align*}
for some open and connected set $U\subseteq\partial\Omega$ such that $\boldsymbol{x}\in U$ and $\boldsymbol{\sigma}(U)>0$. Choose $r>0$ such that $B(\boldsymbol{x},r)\cap\partial\Omega$ is contained in $U$, where $B(\boldsymbol{x},r)$ denotes an open ball centered at $\boldsymbol{x}$ with radius $r$.

Let $b_l\in{\mathcal I}_3$ be the (noisy) measured local field data obtained from \cref{LBV}, which satisfies $b_l=0$ in ${\mathbb O}\setminus\Omega$. From the viewpoint of \cref{Th1}, we can model it as
\begin{align*}
b_l=A\chi+v+\eta
\end{align*}
where $A={\mathscr F}^{-1}{\mathcal D}{\mathscr F}$ denotes the discretization of the forward operator in \cref{NewModeling}. Here, $\chi\in{\mathcal I}_3$ is the unknown true susceptibility image supported in $\Omega$, $v\in{\mathcal I}_3$ is the incompatibility arising from solving \cref{LBV}, and $\eta$ is the additive noise.

In addition, motivated by the successful results on the wavelet frame based image restoration (e.g. \cite{J.F.Cai2010,J.F.Cai2012}), we assume the sparse approximation of $\chi$ under a given wavelet transformation $W$, and propose our HIRE model as follows:
\begin{align} \min_{\chi,v\in{\mathcal I}_3}~\frac{1}{2}\left\|A\chi+v-b_l\right\|_{\Sigma}^2+\lambda\left\|{\mathscr L} v\right\|_1+\left\|\gamma\cdot W\chi\right\|_{1,2}

\end{align}
where $\left\|\cdot\right\|_{\Sigma}^2=\left\langle\Sigma\cdot,\cdot\right\rangle$ with the SNR weight $\Sigma$ which is estimated from the MRI \cite{T.Liu2011a,C.Milovic2018}.

Here, $\left\|\gamma\cdot W\chi\right\|_{1,2}$ is the isotropic $\ell_1$ norm of the wavelet frame coefficients \cite{J.F.Cai2012} defined as
\begin{align} \left\|\gamma\cdot W\chi\right\|_{1,2}:=\sum_{{\boldsymbol k}\in{\mathbb O}}\sum_{l=0}^{L-1}\gamma_l[{\boldsymbol k}]\left(\sum_{\boldsymbol{\alpha}\in{\mathbb B}}\left|\left(W_{l,\boldsymbol{\alpha}}\chi\right)[{\boldsymbol k}]\right|^2\right)^{1/2}.
\end{align}

For better understanding of our HIRE model, we temporarily assume that $\Sigma=I$ and consider
\begin{align*}
\min_{\chi,v\in{\mathcal I}_3}~\frac{1}{2}\left\|A\chi+v-b_l\right\|_2^2+\lambda\left\|{\mathscr L} v\right\|_1+\left\|\gamma\cdot W\chi\right\|_{1,2}.
\end{align*}
	If $v\equiv0$, our model reduces to the integral approach model:
	\begin{align*}
	\min_{\chi\in{\mathcal I}_3}~\frac{1}{2}\left\|A\chi-b_l\right\|_2^2+\left\|\gamma\cdot W\chi\right\|_{1,2}.
	\end{align*}
	In addition, if we fix $v=b_l-A\chi$, our model reduces to the $\ell_1$ fidelity version of the following differential approach model:
	\begin{align*}
	\min_{\chi\in{\mathcal I}_3}~\frac{1}{2}\left\|{\mathscr L} b_l-{\mathscr L} A\chi\right\|_2^2+\left\|\gamma\cdot W\chi\right\|_{1,2}
	\end{align*}
	as ${\mathscr L} A\chi={\mathscr L} b_l$ discretizes the PDE \cref{QSM_PDE2} in the sense of \cite[Proposition A.1.]{J.K.Choi2014}.

More precisely, let $d=W\chi$, $e={\mathscr L} v$, $f=A\chi$, and $g=v$. Then \cref{WaveletFrameHIRE} is reformulated as follows:
\begin{align*}
&\min_{\chi,v,d,e,f,g}~\frac{1}{2}\left\|f+g-b_l\right\|_{\Sigma}^2+\lambda\left\|e\right\|_1+\left\|\gamma\cdot d\right\|_{1,2}\\
&\text{subject to}~d=W\chi,~e={\mathscr L} v,~f=A\chi,~\text{and}~g=v.
\end{align*}

\caption{Split Bregman Algorithm for \eqref{WaveletFrameHIRE}} \begin{algorithmic}
\STATE{\textbf{Initialization:} $\chi^0$, $v^0$, $d^0$, $e^0$, $f^0$, $g^0$, $p^0$, $q^0$, $r^0$, $s^0$}
\FOR{$k=0$, $1$, $2$, $\cdots$}
\STATE{Update $\chi$ and $v$:
\begin{align}
\chi^{k+1}&=\operatornamewithlimits{argmin}_{\chi}~\frac{\beta}{2}\|A\chi-f^k+r^k\|_2^2+\frac{\beta}{2}\|W\chi-d^k+p^k\|_2^2 \\
v^{k+1}&=\operatornamewithlimits{argmin}_{v}~\frac{\beta}{2}\|v-g^k+s^k\|_2^2+\frac{\beta}{2}\|{\mathscr L} v-e^k+q^k\|_2^2 \end{align}
Update $d$, $e$, $f$, and $g$:
\begin{align}
d^{k+1}&=\operatornamewithlimits{argmin}_d~\left\|\gamma\cdot d\right\|_{1,2}+\frac{\beta}{2}\|d-W\chi^{k+1}-p^k\|_2^2 \\
e^{k+1}&=\operatornamewithlimits{argmin}_e~\lambda\left\|e\right\|_1+\frac{\beta}{2}\|e-{\mathscr L} v^{k+1}-q^k\|_2^2 \\
f^{k+1}&=\operatornamewithlimits{argmin}_f~\frac{1}{2}\|f+g^k-b_l\|_{\Sigma}^2+\frac{\beta}{2}\|f-A\chi^{k+1}-r^k\|_2^2 \\
g^{k+1}&=\operatornamewithlimits{argmin}_g~\frac{1}{2}\|g+f^{k+1}-b_l\|_{\Sigma}^2+\frac{\beta}{2}\|g-v^{k+1}-s^k\|_2^2 \end{align}
Update $p$, $q$, $r$, and $s$:
\begin{align}
p^{k+1}&=p^k+W\chi^{k+1}-d^{k+1} \\
q^{k+1}&=q^k+{\mathscr L} v^{k+1}-e^{k+1} \\
r^{k+1}&=r^k+A\chi^{k+1}-f^{k+1} \\
s^{k+1}&=s^k+v^{k+1}-g^{k+1} \end{align}}
\ENDFOR
\end{algorithmic}

\FOR{$k=0$, $1$, $2$, $\cdots$}
\STATE{Update $\chi$ and $v$:
\begin{align}
\chi^{k+1}&=\operatornamewithlimits{argmin}_{\chi}~\frac{\beta}{2}\|A\chi-f^k+r^k\|_2^2+\frac{\beta}{2}\|W\chi-d^k+p^k\|_2^2 \\
v^{k+1}&=\operatornamewithlimits{argmin}_{v}~\frac{\beta}{2}\|v-g^k+s^k\|_2^2+\frac{\beta}{2}\|{\mathscr L} v-e^k+q^k\|_2^2 \end{align}
Update $d$, $e$, $f$, and $g$:
\begin{align}
d^{k+1}&=\operatornamewithlimits{argmin}_d~\left\|\gamma\cdot d\right\|_{1,2}+\frac{\beta}{2}\|d-W\chi^{k+1}-p^k\|_2^2 \\
e^{k+1}&=\operatornamewithlimits{argmin}_e~\lambda\left\|e\right\|_1+\frac{\beta}{2}\|e-{\mathscr L} v^{k+1}-q^k\|_2^2 \\
f^{k+1}&=\operatornamewithlimits{argmin}_f~\frac{1}{2}\|f+g^k-b_l\|_{\Sigma}^2+\frac{\beta}{2}\|f-A\chi^{k+1}-r^k\|_2^2 \\
g^{k+1}&=\operatornamewithlimits{argmin}_g~\frac{1}{2}\|g+f^{k+1}-b_l\|_{\Sigma}^2+\frac{\beta}{2}\|g-v^{k+1}-s^k\|_2^2 \end{align}
Update $p$, $q$, $r$, and $s$:
\begin{align}
p^{k+1}&=p^k+W\chi^{k+1}-d^{k+1} \\
